window.HOEREN_TESTS[83] = {"id":"in-der-tourist-information","name":"In der Tourist-Information","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Gäste: Willkommen in unserer Stadt. Die große Stadtführung beginnt heute nicht um 14 Uhr und auch nicht um 16 Uhr, sondern wegen des Regens schon um 11 Uhr am Vormittag. Treffpunkt ist vor dem Rathaus. Die Führung dauert zwei Stunden. Bitte ziehen Sie sich warm an. Wir freuen uns auf Sie!","gender":"f","q":"Wann beginnt die Stadtführung heute?","opts":["Um 16 Uhr.","Um 14 Uhr.","Um 11 Uhr."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Wir sind in München und wissen nicht, was wir machen sollen. Ich war in der Tourist-Info, die haben tolle Tipps gegeben. Es gibt ein Museum, das dich interessieren würde, und einen schönen Markt. Sollen wir uns morgen treffen? Ruf zurück, bis bald!","gender":"m","q":"Wo war Markus?","opts":["Im Museum.","Auf dem Markt.","In der Tourist-Information."],"correct":2},{"transcript":"Achtung Besucher: Mit der Gästekarte fahren Sie kostenlos mit Bus und Bahn in der ganzen Stadt. Außerdem bekommen Sie in vielen Museen Rabatt. Die Karte gilt drei Tage und kostet 20 Euro. Sie ist nur hier in der Tourist-Information erhältlich. Fragen Sie unsere Mitarbeiter. Viel Spaß!","gender":"m","q":"Was kann man mit der Gästekarte machen?","opts":["Kostenlos essen.","Kostenlos Bus und Bahn fahren.","Kostenlos übernachten."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Hör mal, ich plane mit der Familie einen Städtetrip und brauche Tipps. In der Tourist-Info gibt es kostenlose Stadtpläne und sogar eine Liste mit guten Restaurants für Kinder. Ich rufe da gleich mal an. Hast du eine Stadt, die du empfehlen kannst? Melde dich, danke!","gender":"f","q":"Was gibt es in der Tourist-Info kostenlos?","opts":["Stadtpläne.","Eintrittskarten.","Essen."],"correct":0},{"transcript":"Liebe Gäste: Am Wochenende findet ein großes Stadtfest statt. Es gibt Musik, Essen aus vielen Ländern und ein Feuerwerk am Samstagabend. Der Eintritt ist frei. Wegen des Festes sind einige Straßen gesperrt. Nutzen Sie am besten Bus und Bahn. Kommen Sie und feiern Sie mit uns!","gender":"f","q":"Wann ist das Feuerwerk?","opts":["Am Freitag.","Am Samstagabend.","Am Sonntag."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer möchte was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Wir stehen am Schalter. Was wollen wir der Gruppe heute zeigen?"},{"speaker":"Lisa","gender":"f","text":"Ich habe eine Karte von der Stadt. Fünf Leute haben Wünsche und der Tag ist nicht lang."},{"speaker":"Lukas","gender":"m","text":"Ich möchte eine Stadtführung. Ein Mensch von hier soll uns die alten Straßen zeigen."},{"speaker":"Lisa","gender":"f","text":"Die beginnt um zehn. Will jemand in den Zoo?"},{"speaker":"Lukas","gender":"m","text":"Für den Zoo haben wir keine Zeit. Der liegt auch weit draußen."},{"speaker":"Lisa","gender":"f","text":"Ich selbst will ins Museum. Dort hängt ein großes Bild."},{"speaker":"Lukas","gender":"m","text":"Das schaffen wir vor dem Essen. Tom bleibt nicht gern nur an Land."},{"speaker":"Lisa","gender":"f","text":"Tom möchte eine Bootsfahrt. Er will eine Stunde auf dem Wasser sein."},{"speaker":"Lukas","gender":"m","text":"Spielt am Abend jemand im Theater?"},{"speaker":"Lisa","gender":"f","text":"Ins Theater geht keiner von uns. Wir bleiben lieber draußen."},{"speaker":"Lukas","gender":"m","text":"Sara will von oben auf die Stadt sehen."},{"speaker":"Lisa","gender":"f","text":"Sara möchte auf den Aussichtsturm. Oben sieht man wirklich alles."},{"speaker":"Lukas","gender":"m","text":"Die Treppe ist lang. Tim sucht dort Essen und viele Leute."},{"speaker":"Lisa","gender":"f","text":"Tim möchte auf den Markt. Er sucht Brot und ein kleines Geschenk."},{"speaker":"Lukas","gender":"m","text":"Der Markt ist bis vier offen."},{"speaker":"Lisa","gender":"f","text":"Wir bleiben bei diesem Plan."}],"options":[{"letter":"a","text":"Park"},{"letter":"b","text":"Bootsfahrt"},{"letter":"c","text":"Zoo"},{"letter":"d","text":"Museum"},{"letter":"e","text":"Aussichtsturm"},{"letter":"f","text":"Stadtführung"},{"letter":"g","text":"Markt"},{"letter":"h","text":"Theater"},{"letter":"i","text":"Shopping"}],"items":[{"person":"Lukas","correct":"f"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"b"},{"person":"Sara","correct":"e"},{"person":"Tim","correct":"g"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Touristin","gender":"f","text":"Guten Tag, wie komme ich zum Schloss? Mit dem Bus oder zu Fuß?"},{"speaker":"Mitarbeiter","gender":"m","text":"Mit der Linie 5, vier Stationen, das dauert etwa 10 Minuten. Zu Fuß ist es länger."},{"speaker":"Touristin","gender":"f","text":"Und zu Fuß? Eine Stunde, oder schneller?"},{"speaker":"Mitarbeiter","gender":"m","text":"Zu Fuß etwa 30 Minuten, nicht 10 Minuten und nicht eine Stunde. Der Weg ist schön durch den Park."},{"speaker":"Touristin","gender":"f","text":"Dann gehe ich zu Fuß, 30 Minuten sind okay. Danke."}],"q":"Wie lange dauert es zu Fuß zum Schloss?","opts":["30 Minuten.","10 Minuten.","Eine Stunde."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, was kostet die Stadtführung? 12 Euro für alle?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Erwachsene 12 Euro, Kinder 6 Euro. 30 Euro wäre für eine ganze Familie."},{"speaker":"Mann","gender":"m","text":"Wir sind zwei Erwachsene und ein Kind. Was kostet das Kind?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Das Kind kostet 6 Euro, nicht 12 und nicht 30. Zusammen macht das 30 Euro für Sie alle."},{"speaker":"Mann","gender":"m","text":"Gut, dann drei Karten, zwei Erwachsene und ein Kind für 6 Euro. Danke."}],"q":"Was kostet die Führung für ein Kind?","opts":["12 Euro.","30 Euro.","6 Euro."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Welches Museum lohnt sich heute? Ist am Sonntag oder Samstag etwas zu?"},{"speaker":"Mitarbeiter","gender":"m","text":"Das Kunstmuseum ist großartig. Samstags und sonntags ist es offen, montags ist zu."},{"speaker":"Frau","gender":"f","text":"Ist es heute geöffnet? Heute ist nicht Montag, oder?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, bis 18 Uhr. Montags ist zu, nicht sonntags und nicht samstags. Heute können Sie hingehen."},{"speaker":"Frau","gender":"f","text":"Prima, dann gehe ich heute ins Museum. Danke."}],"q":"Wann ist das Museum geschlossen?","opts":["Samstags.","Sonntags.","Montags."],"correct":2},{"lines":[{"speaker":"Tourist","gender":"m","text":"Guten Tag, haben Sie einen Stadtplan? Ich brauche keine Eintrittskarte und kein Buch."},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, hier, der Stadtplan ist kostenlos. Eintrittskarten und Bücher verkaufen wir auch, aber der Plan ist umsonst."},{"speaker":"Tourist","gender":"m","text":"Auch auf Englisch? Super, dann nehme ich den Plan."},{"speaker":"Mitarbeiterin","gender":"f","text":"Natürlich, in mehreren Sprachen. Hier ist der kostenlose Stadtplan, nicht die Karte und nicht das Buch."},{"speaker":"Tourist","gender":"m","text":"Vielen Dank, der Plan reicht mir."}],"q":"Was bekommt der Tourist?","opts":["Eine Eintrittskarte.","Einen kostenlosen Stadtplan.","Ein Buch."],"correct":1},{"lines":[{"speaker":"Reisende","gender":"f","text":"Wo kann ich gut und günstig essen? Am Bahnhof oder im Hotel?"},{"speaker":"Mitarbeiter","gender":"m","text":"Am Bahnhof ist es teuer, und im Hotel oft auch. Besser in der Altstadt."},{"speaker":"Reisende","gender":"f","text":"In der Altstadt? Mit lokalen Gerichten, nicht nur am Bahnhof?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, in der Altstadt gibt es viele kleine Lokale. Nicht am Bahnhof und nicht im Hotel, dort ist es teurer."},{"speaker":"Reisende","gender":"f","text":"Dann esse ich in der Altstadt. Markieren Sie mir bitte zwei Lokale."}],"q":"Wo soll die Reisende essen?","opts":["Am Bahnhof.","In der Altstadt.","Im Hotel."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Vogel, einem Mitarbeiter der Tourist-Information. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Vogel, was wollen die Touristen am häufigsten wissen?"},{"speaker":"Vogel","gender":"m","text":"Den Weg, ganz klar. Wie komme ich zum Schloss, zum Museum, zum Bahnhof? Obwohl heute jeder ein Handy mit Karte hat, fragen die Leute lieber einen echten Menschen. Außerdem wollen sie wissen, was sich wirklich lohnt und wo man gut essen kann."},{"speaker":"Reporterin","gender":"f","text":"Hat sich Ihre Arbeit durch das Internet verändert?"},{"speaker":"Vogel","gender":"m","text":"Sehr, früher kamen die Leute ohne Plan und wir haben alles erklärt. Heute haben viele schon online recherchiert. Aber genau da können wir helfen: Wir kennen die Geheimtipps, die nicht im Internet stehen. Den kleinen Aussichtspunkt, das nette Café in der Seitenstraße."},{"speaker":"Reporterin","gender":"f","text":"Was empfehlen Sie den Gästen besonders?"},{"speaker":"Vogel","gender":"m","text":"Die Stadt zu Fuß zu erkunden, nicht nur die großen Sehenswürdigkeiten abzuhaken. Das Schöne liegt oft abseits. Setzen Sie sich in ein Café, beobachten Sie die Menschen. Reden Sie mit den Einheimischen. So lernt man eine Stadt wirklich kennen, nicht durch schnelle Fotos."},{"speaker":"Reporterin","gender":"f","text":"Gibt es zu viele Touristen in den Städten?"},{"speaker":"Vogel","gender":"m","text":"In manchen Städten leider ja. Im Sommer ist es teils zu voll, das stört auch die Bewohner. Wir versuchen, die Gäste auf weniger bekannte Orte zu lenken. Und wir empfehlen, im Frühling oder Herbst zu reisen. Dann ist es ruhiger und oft auch schöner."},{"speaker":"Reporterin","gender":"f","text":"Was macht Ihnen an Ihrer Arbeit am meisten Freude?"},{"speaker":"Vogel","gender":"m","text":"Wenn die Leute glücklich zurückkommen und sagen: Ihr Tipp war fantastisch! Ich liebe meine Stadt und freue mich, wenn andere sie auch lieben lernen. Jeden Tag treffe ich Menschen aus aller Welt. Das ist wie reisen, ohne wegzufahren. Ich habe den schönsten Beruf."}],"items":[{"q":"Die Touristen fragen am häufigsten nach dem Weg.","correct":"ja"},{"q":"Herr Vogel sagt, das Internet hat seine Arbeit nicht verändert.","correct":"nein"},{"q":"Er empfiehlt, die Stadt zu Fuß zu erkunden.","correct":"ja"},{"q":"Er findet, in manchen Städten gibt es zu viele Touristen.","correct":"ja"},{"q":"Ihm macht seine Arbeit keine Freude.","correct":"nein"}]}]};
